class ShoppingCart {
    private String customerId;
    private int itemCount;
    private double subtotal;
    private double discountRate; // e.g. 0.10 for 10%

    public ShoppingCart(String customerId) {
        this.customerId = customerId;
        this.itemCount = 0;
        this.subtotal = 0.0;
        this.discountRate = 0.0;
    }

    public void addItem(double itemPrice) {
        if (itemPrice <= 0) {
            System.out.println("Invalid item price: $" + itemPrice);
            return;
        }
        this.itemCount++;
        this.subtotal += itemPrice;
        System.out.println("Added item ($" + itemPrice + "). Cart items: " + itemCount);
    }

    public void applyCoupon(String couponCode) {
        if ("SAVE10".equalsIgnoreCase(couponCode)) {
            this.discountRate = 0.10;
            System.out.println("Coupon SAVE10 applied (10% off).");
        } else if ("SAVE20".equalsIgnoreCase(couponCode) && subtotal >= 100.0) {
            this.discountRate = 0.20;
            System.out.println("Coupon SAVE20 applied (20% off).");
        } else {
            System.out.println("Coupon rejected or order minimum not met.");
        }
    }

    public double calculateFinalTotal() {
        double discountAmount = subtotal * discountRate;
        return subtotal - discountAmount;
    }

    public int getItemCount() { return itemCount; }
    public double getSubtotal() { return subtotal; }
}

public class Main {
    public static void main(String[] args) {
        ShoppingCart cart = new ShoppingCart("CUST-4401");
        cart.addItem(60.0);
        cart.addItem(50.0); // Subtotal: 110.0
        cart.applyCoupon("SAVE20"); // Eligible for 20%
        System.out.println("Final Checkout Total: $" + cart.calculateFinalTotal());
    }
}

