class LoyaltyAccount {
    private String memberName;
    private int pointsBalance;
    private String tierLevel; // Bronze, Silver, Gold

    public LoyaltyAccount(String name) {
        this.memberName = name;
        this.pointsBalance = 0;
        this.tierLevel = "Bronze";
    }

    public void earnPoints(int points) {
        if (points <= 0) return;
        this.pointsBalance += points;
        updateTier();
    }

    public boolean redeemPoints(int points) {
        if (points > 0 && points <= pointsBalance) {
            this.pointsBalance -= points;
            updateTier();
            return true;
        }
        return false;
    }

    // Private helper: keeps tier synchronized with points
    private void updateTier() {
        if (pointsBalance >= 1000) {
            tierLevel = "Gold";
        } else if (pointsBalance >= 500) {
            tierLevel = "Silver";
        } else {
            tierLevel = "Bronze";
        }
    }

    public int getPointsBalance() { return pointsBalance;
    }
    public String getTierLevel() { return tierLevel; }
}

public class Main {
    public static void main(String[] args) {
        LoyaltyAccount acc = new LoyaltyAccount("Neha");
        acc.earnPoints(300); // 300 -> Bronze
        System.out.println("Current Tier: " + acc.getTierLevel());
        acc.earnPoints(300); // 600 -> Silver
        System.out.println("Promoted Tier: " + acc.getTierLevel());
    }
}

