class CoffeeOrder {
    private int shots = 0;

    public void addShot() {
        if (shots < 5) {
            shots++;
        }
    }

    public double calculatePrice() {
        return 2.50 + (shots * 0.75);
    }

    public int getShots() {
        return shots;
    }
}

public class Main {
