        CoffeeOrder order = new CoffeeOrder();
        order.addShot();
        order.addShot();
        System.out.println("Coffee total: $" + order.calculatePrice());
    }
}

class RideFare {
    private double distanceKm;
    private boolean surgePricing;

    public RideFare(double distance) {
        this.distanceKm = distance > 0 ? distance : 1.0;
        this.surgePricing = false;
    }

    public void setSurge(boolean surge) {
        this.surgePricing = surge;
    }

    public double calculateTotalFare() {
        double base = distanceKm * 2.0;
        return surgePricing ? base * 1.5 : base;
    }
}

public class Main {
    public static void main(String[] args) {
        RideFare ride = new RideFare(10.0);
        ride.setSurge(true);
        System.out.println("Total fare: $" + ride.calculateTotalFare());
    }
}

class CheckingAccount {
    private double balance;
    private double overdraftLimit;

    public CheckingAccount(double initialBalance, double overdraft) {
        this.balance = initialBalance >= 0 ? initialBalance : 0.0;
        this.overdraftLimit = overdraft >= 0 ? overdraft : 0.0;
    }

    public void deposit(double amount) {
        if (amount > 0) {
            balance += amount;
        }
    }

    public boolean withdraw(double amount) {
        if (amount > 0 && amount <= (balance + overdraftLimit)) {
            balance -= amount;
            return true;
        } else {
            System.out.println("Transaction Declined");
            return false;
        }
    }

    public double getBalance() {
        return balance;
    }
}

public class Main {
    public static void main(String[] args) {
        CheckingAccount acc = new CheckingAccount(50.0, 50.0);
        acc.withdraw(80.0);
        acc.withdraw(50.0);
        System.out.println("Final balance: $" + acc.getBalance());
    }
}

