class OrderInvoice {
    private int itemCount = 0;
    private double totalAmount = 0.0;

    public void addItems(int count, double pricePerItem) {
        if (count > 0 && pricePerItem > 0) {
            this.itemCount += count;
            this.totalAmount += (count * pricePerItem);
        }
    }

    public int getItemCount() { return itemCount; }
    public double getTotalAmount() { return totalAmount; }
}

public class Main {
    public static void main(String[] args) {
        OrderInvoice order = new OrderInvoice();
        order.addItems(3, 15.0);
        System.out.println("Order verified: " + order.getItemCount() + " items, Total: $" + order.getTotalAmount());
    }
}

class EcoThermostat {
    private double targetTemp;
    private boolean ecoMode;

    public EcoThermostat(double initialTemp) {
        this.ecoMode = false;
        setTargetTemp(initialTemp);
    }

    public void setEcoMode(boolean eco) {
        this.ecoMode = eco;
        if (ecoMode) {
            if (targetTemp > 22.0) targetTemp = 22.0;
            if (targetTemp < 18.0) targetTemp = 18.0;
        }
    }

    public void setTargetTemp(double temp) {
        double max = ecoMode ? 22.0 : 28.0;
        double min = ecoMode ? 18.0 : 16.0;
        if (temp > max) {
            this.targetTemp = max;
        } else if (temp < min) {
            this.targetTemp = min;
        } else {
            this.targetTemp = temp;
        }
    }

    public double getTargetTemp() { return targetTemp; }
    public boolean isEcoMode() { return ecoMode; }
}

public class Main {
    public static void main(String[] args) {
        EcoThermostat t = new EcoThermostat(20.0);
        t.setEcoMode(true);
        t.setTargetTemp(26.0);
        System.out.println("Target set to: " + t.getTargetTemp() + " C");
    }
}
